import Image from "next/image";
import { MarkdownBody } from "./MarkdownBody";

const TYPE_STYLES = {
  auspicious: "border-l-4 border-emerald-400 bg-emerald-50",
  inauspicious: "border-l-4 border-red-400 bg-red-50",
  neutral: "border-l-4 border-gray-300 bg-gray-50",
} as const;

type Props = {
  heading: string;
  body: string;
  type: string;
  image?: string;
};

export function DreamSection({ heading, body, type, image }: Props) {
  const style =
    TYPE_STYLES[type as keyof typeof TYPE_STYLES] ?? TYPE_STYLES.neutral;

  return (
    <section className="mt-8">
      <h2 className="mb-3 text-xl font-semibold">{heading}</h2>
      <div className={`rounded-xl p-5 ${style}`}>
        {image && (
          <div className="relative mb-4 w-full overflow-hidden rounded-lg aspect-[3/2]">
            <Image
              src={image}
              alt={heading}
              fill
              className="object-cover object-center"
              sizes="(max-width: 640px) 100vw, 680px"
            />
          </div>
        )}
        <MarkdownBody className="text-gray-800">{body}</MarkdownBody>
      </div>
    </section>
  );
}

import { MarkdownBody } from "./MarkdownBody";

type Variation = {
  keyword: string;
  heading: string;
  body: string;
};

type Props = {
  heading: string;
  variations: Variation[];
};

export function DreamVariations({ heading, variations }: Props) {
  if (!variations?.length) return null;

  return (
    <section className="mt-10">
      <h2 className="mb-5 text-xl font-semibold">{heading}</h2>
      <div className="space-y-6">
        {variations.map((v, i) => (
          <div key={i}>
            <h3 className="mb-2 text-base font-semibold text-indigo-700">
              {v.heading}
            </h3>
            <MarkdownBody className="text-gray-700">{v.body}</MarkdownBody>
          </div>
        ))}
      </div>
    </section>
  );
}

import Image from "next/image";
import type { Locale } from "@/i18n/routing";
import { MarkdownBody } from "./MarkdownBody";

type Props = {
  title: string;
  intro: string;
  heroImage?: string;
  locale: Locale;
};

export function DreamHero({ title, intro, heroImage, locale: _locale }: Props) {
  return (
    <div className="mb-8">
      {/*
        Single 3:2 image from Midjourney.
        Mobile: 1:1 container → crops sides, keeps centered subject.
        Desktop: 16:9 container → crops top/bottom slightly.
        object-position: center ensures the focal point is always visible.
      */}
      {heroImage ? (
        <div className="relative mb-6 w-full overflow-hidden rounded-2xl aspect-square sm:aspect-video">
          <Image
            src={heroImage}
            alt={title}
            fill
            className="object-cover object-center"
            priority
            sizes="(max-width: 640px) 100vw, 768px"
          />
        </div>
      ) : (
        <div className="mb-6 w-full rounded-2xl bg-gradient-to-br from-indigo-100 to-purple-100 aspect-square sm:aspect-video" />
      )}

      <h1 className="mb-4 text-2xl font-bold leading-snug sm:text-3xl">
        {title}
      </h1>

      <MarkdownBody className="text-base leading-relaxed text-gray-700 sm:text-lg">
        {intro}
      </MarkdownBody>
    </div>
  );
}

